package com.buukle.agent.common.util;

/**
 * Dotted numeric version comparison, used by the browser-extension compatibility gate.
 *
 * <p>The Chrome extension version is generated by the release workflow from the git tag
 * ({@code v1.0.171-alpha} -> {@code 1.0.171}), while the minimum version is entered manually
 * in system config and may be written as {@code 1.0.171} or {@code v1.0.171-alpha}. Both sides
 * are normalized here: optional {@code v} prefix, pre-release/build suffixes stripped, missing
 * segments treated as 0.
 */
public final class VersionUtils {

    private VersionUtils() {
    }

    /**
     * True when {@code current} is present and greater than or equal to {@code min}.
     *
     * <p>Returns false for a blank current version: extensions older than the version-gate
     * release never report one, and must be treated as too old.
     */
    public static boolean isAtLeast(String current, String min) {
        if (current == null || current.isBlank() || min == null || min.isBlank()) {
            return false;
        }
        return compare(current, min) >= 0;
    }

    /** Compares two dotted numeric versions; returns -1 / 0 / 1. */
    public static int compare(String a, String b) {
        int[] pa = parse(a);
        int[] pb = parse(b);
        int length = Math.max(pa.length, pb.length);
        for (int i = 0; i < length; i++) {
            int left = i < pa.length ? pa[i] : 0;
            int right = i < pb.length ? pb[i] : 0;
            if (left != right) {
                return left < right ? -1 : 1;
            }
        }
        return 0;
    }

    private static int[] parse(String version) {
        if (version == null) {
            return new int[0];
        }
        String normalized = version.trim();
        if (normalized.startsWith("v") || normalized.startsWith("V")) {
            normalized = normalized.substring(1);
        }
        int cutoff = normalized.length();
        int dash = normalized.indexOf('-');
        if (dash >= 0) {
            cutoff = Math.min(cutoff, dash);
        }
        int plus = normalized.indexOf('+');
        if (plus >= 0) {
            cutoff = Math.min(cutoff, plus);
        }
        normalized = normalized.substring(0, cutoff);
        if (normalized.isEmpty()) {
            return new int[0];
        }
        String[] parts = normalized.split("\\.");
        int[] parsed = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            try {
                parsed[i] = Integer.parseInt(parts[i].trim());
            } catch (NumberFormatException e) {
                parsed[i] = 0;
            }
        }
        return parsed;
    }
}
